update mst_doc set doc_nm = #{docNm}, use_yn = #{useYn}, remark = #{remark},
                   row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where doc_id = #{id} and row_ver = #{rowVer}

mapper.select:
select 
  from mst_doc_rev r join mst_doc d on d.doc_id = r.doc_id left join apr_request a on a.apr_id = r.apr_id
 where r.doc_rev_id = #{id}

mapper.update:
update mst_doc_rev set status = 'IN_APPROVAL', apr_id = #{aprId}, submitted_at = now(), submitted_by = #{by},
                       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where doc_rev_id = #{id} and status = 'DRAFT' and row_ver = #{rowVer}

update mst_doc_rev set status = 'OBSOLETE', obsoleted_at = now(), obsoleted_by = #{by},
                       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where doc_id = #{docId} and status = 'RELEASED'

update mst_doc_rev set status = 'RELEASED', released_at = now(), released_by = #{by},
                       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where doc_rev_id = #{id} and status in ('DRAFT', 'IN_APPROVAL')

update mst_doc_rev set status = 'OBSOLETE', obsoleted_at = now(), obsoleted_by = #{by},
                       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where doc_rev_id = #{id} and status in ('DRAFT', 'RELEASED') and row_ver = #{rowVer}

mapper.select:
select 
  from mst_doc_rev r join mst_doc d on d.doc_id = r.doc_id left join apr_request a on a.apr_id = r.apr_id
 where r.source_key = #{key}
